1	/* ==========================================================================
2	   BusinessServices — Design System
3	   Warm premium service brand: teal-ink structure, brass action color.
4	   Layers: tokens · reset · layout · header/footer · buttons · hero ·
5	           cards · portfolio/prices/about · contacts · a11y · responsive
6	   ========================================================================== */
7	
8	/* ==========================================================================
9	   1. TOKENS
10	   ========================================================================== */
11	:root {
12	    /* --- Color: structure --- */
13	    --ink:              #0F2A2E;
14	    --ink-2:            #0A1F22;
15	    --canvas:           #F7F5F1;
16	    --canvas-2:         #EFEBE4;
17	    --surface:          #FFFFFF;
18	    --border:           #E6E0D6;
19	    --border-strong:    #D6CDBE;
20	
21	    /* --- Color: text --- */
22	    --text:             #1A2E2C;
23	    --text-2:           #5C6B68;
24	    --text-3:           #8A938F;
25	    --text-on-ink:      #EDE7DD;
26	    --text-on-ink-2:    #A9B5B2;
27	
28	    /* --- Color: action --- */
29	    --accent:           #B26A20;
30	    --accent-hover:     #8F5318;
31	    --accent-soft:      #FBF1E3;
32	    --accent-line:      #E8CFA8;
33	    --accent-on-ink:    #E0A458;
34	
35	    /* --- Color: semantic --- */
36	    --price:            #2F6B4F;
37	    --badge-repair-bg:      #F6E9D5;
38	    --badge-repair-fg:      #8A5A16;
39	    --badge-cleaning-bg:    #DDE9E7;
40	    --badge-cleaning-fg:    #1F5551;
41	    --badge-montage-bg:     #DFE9DD;
42	    --badge-montage-fg:     #2F5A32;
43	
44	    /* --- Type --- */
45	    --font-display: 'Playfair Display', Georgia, 'Times New Roman', serif;
46	    --font-sans: 'Manrope', -apple-system, BlinkMacSystemFont, 'Segoe UI',
47	                 Roboto, Helvetica, Arial, sans-serif;
48	
49	    --fs-display:   clamp(2.25rem, 1.6rem + 2.6vw, 3.4rem);
50	    --fs-title:     clamp(1.9rem, 1.5rem + 1.6vw, 2.6rem);
51	    --fs-section:   clamp(1.5rem, 1.3rem + 0.9vw, 1.95rem);
52	    --fs-card:      1.2rem;
53	    --fs-body:      1rem;
54	    --fs-sm:        0.875rem;
55	    --fs-micro:     0.72rem;
56	
57	    /* --- Space (4px base) --- */
58	    --s1: 4px;  --s2: 8px;  --s3: 12px; --s4: 16px; --s5: 24px;
59	    --s6: 32px; --s7: 48px; --s8: 64px; --s9: 96px;
60	
61	    /* --- Radii --- */
62	    --r-sm: 8px; --r-md: 12px; --r-lg: 18px; --r-pill: 999px;
63	
64	    /* --- Elevation (warm-tinted, never pure black) --- */
65	    --sh-1: 0 1px 2px rgba(23, 36, 34, .05);
66	    --sh-2: 0 2px 4px rgba(23, 36, 34, .04),
67	            0 10px 20px -8px rgba(23, 36, 34, .10);
68	    --sh-3: 0 4px 8px rgba(23, 36, 34, .05),
69	            0 20px 40px -16px rgba(23, 36, 34, .20);
70	
71	    /* --- Layout --- */
72	    --header-h: 68px;
73	    --wrap: 1200px;
74	
75	    /* --- Motion --- */
76	    --t-fast: 140ms cubic-bezier(.2, .6, .3, 1);
77	    --t-base: 240ms cubic-bezier(.2, .6, .3, 1);
78	}
79	
80	/* ==========================================================================
81	   2. RESET & BASE
82	   ========================================================================== */
83	*, *::before, *::after { box-sizing: border-box; }
84	* { margin: 0; padding: 0; }
85	
86	html {
87	    -webkit-text-size-adjust: 100%;
88	    scroll-behavior: smooth;
89	}
